// This file is generated by AI.

// 文本预处理选项卡: Monaco 编辑器 (上) + 步骤面板 (下)。
// 会话与编辑器为每选项卡独立实例, 可多开。

import { Button } from '@fluentui/react-components';
import * as monaco from 'monaco-editor';
import { useEffect, useReducer, useRef, useState } from 'react';

import { LANGUAGE_ID as WEBGAL_LANGUAGE_ID } from '../lsp/monaco';
import { useAppStore } from '../state/store';
import { NOVEL_LANGUAGE_ID, createEditorHost, createNovelModel } from './monaco';
import { getOrCreateSession, novelModelUri, releaseSession } from './registry';
import { NovelSession, type SessionState, type Speaker, type Step } from 'webgal-novel-preprocess';

const EMPTY_STATE: SessionState = {
  step: 1,
  text: '',
  speakers: [],
  warnings: [],
  diagnostics: [],
  unresolvedCount: 0,
  pendingConfirm: false,
  canGoBack: false,
  canGoNext: false,
  selectedHeadLine: -1,
};

const STEP_INFO: Record<Step, { label: string; desc: string; tips: string[] }> = {
  1: {
    label: '输入文本',
    desc: '粘贴小说原文，标点、空格与对话会在下一步自动规整。',
    tips: ['把整篇或整段小说原文粘贴到上方编辑器。', '可以任意分段，空行会被自动清理。'],
  },
  2: {
    label: '格式化与断句',
    desc: '自动处理已完成，可手动微调后再继续。',
    tips: [
      '以 : 开头的一行为旁白；以 %: 开头的一行为待分配对话；无前缀的一行跟随上一句对话的说话者。',
      '对话内容已去掉外层引号，句内引号已规范为双引号。',
      '可直接编辑上方文本；Shift+Alt+F 可重新规整行内空格。',
    ],
  },
  3: {
    label: '设置对话者',
    desc: '进入后自动选中第一段对话，按人物键位分配说话者。',
    tips: [
      '光标移动到某段对话时会自动选中整段（旁白不选）。',
      '按键盘 1-9 或 A-Z 对应人物键位，即可为当前对话段设置说话者；分配后自动跳到下一段。',
      '在下方人物面板填写名称与可选的 figureId；键位为面板上显示的编号。',
      '分配后编辑器内显示为「编号-名称」，导出时自动去掉编号前缀。',
    ],
  },
  4: {
    label: '生成脚本',
    desc: '脚本已生成（只读），复制后粘贴到任意场景即可。',
    tips: ['旁白为 :内容;，对话为 人物名:内容;（可带 -figureId）。', '可手动框选复制，或点击「复制全文」。'],
  },
};

export function PreprocessTab({ id }: { id: string }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const sessionRef = useRef<NovelSession | null>(null);
  const modelRef = useRef<monaco.editor.ITextModel | null>(null);
  const [session, setSession] = useState<NovelSession | null>(null);
  const [copied, setCopied] = useState(false);
  const [, force] = useReducer((x: number) => x + 1, 0);

  const settings = useAppStore((s) => s.settings);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // 会话与 model 跨挂载存活 (切走再切回不丢状态)。
    const model = createNovelModel(monaco, novelModelUri(id));
    modelRef.current = model;
    const editor = monaco.editor.create(container, {
      model,
      automaticLayout: true,
      fontFamily: settings.editorFontFamily,
      fontSize: settings.editorFontSize,
      wordWrap: 'on',
      minimap: { enabled: false },
      // 生成脚本 (第 4 步) 切换为 webgal 语言后需要语义高亮。
      'semanticHighlighting.enabled': true,
    });

    const host = createEditorHost(monaco, editor);
    const sess = getOrCreateSession(id, host);
    sessionRef.current = sess;
    setSession(sess);

    return () => {
      // 仅解绑宿主并销毁编辑器; 会话与 model 保留在注册表。
      releaseSession(id);
      editor.dispose();
      sessionRef.current = null;
      modelRef.current = null;
      setSession(null);
    };
  }, [id]);

  useEffect(() => {
    if (!session) return;
    return session.subscribe(() => force());
  }, [session]);

  const state = session ? session.getState() : EMPTY_STATE;

  // 步骤 4 切换为 WebGAL 语言以复用语义高亮; 其余步骤为中间格式语言。
  useEffect(() => {
    const model = modelRef.current;
    if (!model) return;
    const lang = state.step === 4 ? WEBGAL_LANGUAGE_ID : NOVEL_LANGUAGE_ID;
    if (model.getLanguageId() !== lang) monaco.editor.setModelLanguage(model, lang);
  }, [state.step]);

  // 第 2 步: 将解析诊断 + 预处理警告写入 Monaco markers (行号与可见文本对齐)。
  useEffect(() => {
    const model = modelRef.current;
    if (!model || state.step !== 2) {
      if (model) monaco.editor.setModelMarkers(model, NOVEL_LANGUAGE_ID, []);
      return;
    }
    const toMarker = (d: { severity: 'error' | 'warning' | 'info'; message: string; line: number }) => ({
      severity:
        d.severity === 'error'
          ? monaco.MarkerSeverity.Error
          : d.severity === 'warning'
            ? monaco.MarkerSeverity.Warning
            : monaco.MarkerSeverity.Info,
      message: d.message,
      startLineNumber: d.line + 1,
      startColumn: 1,
      endLineNumber: d.line + 1,
      endColumn: 1,
    });
    const markers = [
      ...state.diagnostics.map(toMarker),
      // 预处理警告指向其所属的 `;` 注释行。
      ...state.warnings.map((w) => toMarker({ severity: 'warning', message: w.message, line: w.line })),
    ];
    monaco.editor.setModelMarkers(model, NOVEL_LANGUAGE_ID, markers);
  }, [state.step, state.diagnostics, state.warnings]);

  const copyScript = async () => {
    try {
      await navigator.clipboard.writeText(state.text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      // 剪贴板不可用时静默忽略
    }
  };

  const info = STEP_INFO[state.step];

  return (
    <div className="preprocess-tab">
      <div ref={containerRef} className="preprocess-editor" />

      <div className="preprocess-panel">
        <div className="preprocess-step">
          <span className="preprocess-step-idx">步骤 {state.step} / 4</span>
          <span className="preprocess-step-label">{info.label}</span>
          <span className="preprocess-step-desc">{info.desc}</span>
        </div>

        <ul className="preprocess-tips">
          {info.tips.map((t, i) => (
            <li key={i}>{t}</li>
          ))}
        </ul>

        {state.step === 3 && <CharacterPanel session={session} speakers={state.speakers} />}

        <div className="preprocess-actions">
          <Button appearance="secondary" disabled={!state.canGoBack} onClick={() => session?.back()}>
            上一步
          </Button>
          <span className="preprocess-actions-spacer" />
          {state.step === 4 && (
            <Button appearance="primary" onClick={() => void copyScript()}>
              {copied ? '已复制' : '复制全文'}
            </Button>
          )}
          <Button appearance="primary" disabled={!state.canGoNext} onClick={() => session?.next()}>
            下一步
          </Button>
        </div>
      </div>

      <UnresolvedDialog
        open={state.pendingConfirm}
        unresolvedCount={state.unresolvedCount}
        onConfirm={() => session?.resolveUnresolved(true)}
        onCancel={() => session?.resolveUnresolved(false)}
      />
    </div>
  );
}

function CharacterPanel({ session, speakers }: { session: NovelSession | null; speakers: Speaker[] }) {
  return (
    <div className="preprocess-characters">
      <div className="preprocess-characters-grid">
        {speakers.map((s) => (
          <div className="preprocess-character" key={s.key}>
            <span className="preprocess-character-key">{s.key}</span>
            <input
              className="preprocess-character-name"
              placeholder="人物名称"
              title="人物名称 (约 6 个汉字)"
              value={s.name}
              onChange={(e) => session?.updateSpeaker(s.key, { name: e.target.value })}
            />
            <input
              className="preprocess-character-id"
              placeholder="figureId"
              title="figureId (可选, 约 6 个字符)"
              value={s.figureId ?? ''}
              onChange={(e) => session?.updateSpeaker(s.key, { figureId: e.target.value })}
            />
            <button
              className="preprocess-character-remove"
              title="移除人物"
              onClick={() => session?.removeSpeaker(s.key)}
            >
              ×
            </button>
          </div>
        ))}
        <button className="preprocess-character-add" onClick={() => session?.addSpeaker()}>
          + 新增人物
        </button>
      </div>
    </div>
  );
}

function UnresolvedDialog({
  open,
  unresolvedCount,
  onConfirm,
  onCancel,
}: {
  open: boolean;
  unresolvedCount: number;
  onConfirm: () => void;
  onCancel: () => void;
}) {
  if (!open) return null;
  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <div className="modal-surface" onClick={(e) => e.stopPropagation()}>
        <h2 className="modal-title">存在未分配的对话</h2>
        <p>还有 {unresolvedCount} 段对话未设置说话者，是否将其作为旁白处理？</p>
        <div className="modal-actions">
          <Button appearance="secondary" onClick={onCancel}>
            返回继续
          </Button>
          <Button appearance="primary" onClick={onConfirm}>
            作为旁白
          </Button>
        </div>
      </div>
    </div>
  );
}
